SELECT s.*, ci.name AS chemical_name, ur.nickname AS receiver_name FROM stock_in s LEFT JOIN chem_info ci ON s.chemical_id = ci.id LEFT JOIN sys_user ur ON s.receiver_id = ur.id WHERE 1 = 1
AND (s.code LIKE CONCAT('%', #{keyword}, '%') OR s.lot_no LIKE CONCAT('%', #{keyword}, '%'))
AND s.status = #{status} ORDER BY s.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM stock_in s WHERE 1 = 1
AND (s.code LIKE CONCAT('%', #{keyword}, '%') OR s.lot_no LIKE CONCAT('%', #{keyword}, '%'))
AND s.status = #{status}
